  ('491930ed-fb07-5cb3-b874-44394c5b0e00', null, (select id from public.skills where slug = 'read-g6-argument-evidence'), null, 'hard',
   $q$Which statement best evaluates the evidence for the reason about cost?$q$, $q$[{"text":"It is weak, because it is about concerts instead of about money.","is_correct":false,"misconception_token":"misreads-detail"},{"text":"It is strong, because it gives prices and a survey of students who want to play.","is_correct":true},{"text":"It is strong, because it proves every student at Riverside will join the band.","is_correct":false,"misconception_token":"overgeneralizes"},{"text":"It is weak, because it is based only on the author's personal feelings.","is_correct":false,"misconception_token":"misjudges-support"}]$q$::jsonb, $q$It is strong, because it gives prices and a survey of students who want to play.$q$, $q$The cost reason is backed by instrument prices and a survey with numbers, which is solid evidence. It shows many students are held back by cost, but it does not prove every student will join.$q$, 'draft', '83c2be5a-e039-5bbd-84a7-1cf96488553f')
