  ('5702a4ce-da3e-5f66-aaed-e90b9e21d4d4', null, (select id from public.skills where slug = 'read-g6-character-setting-plot'), null, 'hard',
   $q$Which statement best describes how Brisk changes from the beginning of the fable to the end?$q$, $q$[{"text":"She becomes afraid of climbing and stays in the meadow.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"She stops racing and always takes the long trail.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"She goes from ignoring advice to asking for it before she climbs.","is_correct":true},{"text":"She grows faster because of the week she spent resting.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$She goes from ignoring advice to asking for it before she climbs.$q$, $q$At first she laughs at the marmot, but at the end she stops at his rock "each morning before choosing her path." She still races up the upper path on some days, so she does not always take the long trail.$q$, 'draft', 'f550228d-cadc-5fbe-a4fa-c02d3da6697e')
