-- Passage rg6-character-setting-plot-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('105596cb-e9f8-55fb-981b-4c2668ff2b0b', 'rg6-character-setting-plot-p06', (select id from public.skills where slug = 'read-g6-character-setting-plot'), null,
        '6-8', $q$Next Door$q$, $q$The snow came down all night,
and by morning the street was a white sheet
with no tracks on it but the mail carrier's.
Dad handed me a shovel. "Our walk, then hers."

Hers meant Mrs. Lindgren's, next door,
the neighbor who complained when our soccer ball
rolled into her tulips last spring.
I shoveled our walk slowly, hoping she would hire someone else.

Then I saw her at the window,
leaning on a cane, watching the drifts climb her steps.
She did not wave. She only watched.
I picked up the shovel and crossed the yard.

It took an hour. My arms burned.
When I finished, the door opened a crack,
and she handed me a mug of cocoa
and the soccer ball I had not seen since May.

"It's been in my garage," she said. "I was saving it
for whoever finally came over to ask."
Now I shovel her walk before ours,
and some afternoons, I knock just to say hello.$q$, 'draft')
