  ('d5e014a0-7161-576a-8a48-9386651b12ee', null, (select id from public.skills where slug = 'read-g6-figurative-language'), null, 'medium',
   $q$In paragraph 3, Mei Lin's knight "slipped behind Darnell's defenses like a fox entering a henhouse." What does this simile suggest?$q$, $q$[{"text":"The knight sneaked into a dangerous spot and threatened Darnell's pieces.","is_correct":true},{"text":"The knight was knocked off the table and rolled away.","is_correct":false,"misconception_token":"literal-reading"},{"text":"The knight moved back to protect Mei Lin's own king.","is_correct":false,"misconception_token":"confuses-characters"},{"text":"The knight was captured right away by Darnell's pieces.","is_correct":false,"misconception_token":"opposite-meaning"}]$q$::jsonb, $q$The knight sneaked into a dangerous spot and threatened Darnell's pieces.$q$, $q$A fox in a henhouse is a sneaky threat to everything inside, and the next sentence says "Darnell's queen was trapped." The knight attacked; it was not captured.$q$, 'draft', '8c671e9a-bac7-5fc2-8a86-4b9c1076c51a')
