  ('71291270-06ac-569f-97aa-511ef404868a', null, (select id from public.skills where slug = 'read-g6-figurative-language'), null, 'hard',
   $q$In paragraph 5, "release day is a mountaintop" for the team. What does this metaphor suggest?$q$, $q$[{"text":"The team feels nervous and wishes it could go back to the beginning.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Launching the game is a proud high point reached after a long, difficult effort.","is_correct":true},{"text":"Release day is the hardest and most tiring part of making a game.","is_correct":false,"misconception_token":"confuses-climb-with-peak"},{"text":"The team celebrates release day by hiking up a real mountain together.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$Launching the game is a proud high point reached after a long, difficult effort.$q$, $q$A mountaintop is the highest point, reached after "the long climb," which stands for all the months of work. The climb, not the top, is the hard part, so release day itself is the reward.$q$, 'draft', '9d831aac-925a-566a-85a5-cecaadd5b6c0')
